using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Retrieves the value of a specific configuration key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = AppConfiguration.Current;
        return config.TryGetValue(key, out var value)
            ? value
            : $"Key '{key}' not found.";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"), Description("Returns all application configuration as JSON.")]
    public static string GetAllSettings() =>
        JsonSerializer.Serialize(AppConfiguration.Current, AppConfiguration.JsonOptions);

    [McpServerResource(UriTemplate = "config://app/info", Name = "App Info",
        MimeType = "application/json"), Description("Returns application metadata.")]
    public static string GetAppInfo() =>
        JsonSerializer.Serialize(new
        {
            Name = "HttpMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production"
        }, AppConfiguration.JsonOptions);
}

public static class AppConfiguration
{
    public static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    public static Dictionary<string, string> Current { get; } = new()
    {
        ["DatabaseTimeout"] = "30",
        ["MaxRetries"] = "3",
        ["FeatureFlag.DarkMode"] = "true",
        ["ApiBaseUrl"] = "https://api.example.com"
    };
}

